import * as W from './world.js?v=0.4.0';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₺'+Math.round(n).toLocaleString('tr-TR');
const labels={boxing:'Boks',kickboxing:'Kickboks',wrestling:'Güreş',bjj:'BJJ',stamina:'Kondisyon',strength:'Kuvvet'};
const section=(title,note='')=>`<div class="section-head"><h2>${title}</h2><span>${note}</span></div>`;
const button=(label,id,disabled=false,kind='')=>`<button class="${kind}" data-action="world" data-value="${esc(id)}" ${disabled?'disabled':''}>${label}</button>`;
const day=s=>Math.floor(s.hours/24)+1;
const world=s=>s.world||{reputation:0,home:0,sponsor:null,notice:'Mahalle henüz adını bilmiyor. Bir antrenman, bir karşılaşma, bir yeni bağlantı.'};

function costs(s,choice){
 const p=W.choicePreview(s,choice),gains=[p.reward?`+${money(p.reward)}`:'',p.rep?`+${p.rep} itibar`:'',...Object.entries(p.skills).map(([key,n])=>`+${n.toFixed(2)} ${labels[key]}`)].filter(Boolean);
 return `<p class="world-choice-cost">${p.hours} sa${p.cash?' · '+money(p.cash):' · Ücretsiz'}<br>−${p.energy} enerji · −${p.food} tokluk · −${p.sleep} dinçlik${p.health?'<br><strong>−'+p.health+' sağlık</strong>':''}${p.fatigue?' · Yük +'+p.fatigue:''}</p><p class="gain-preview">${gains.map(esc).join(' · ')}</p>`;
}

function cityMap(s){
 const w=world(s),home=W.HOMES[w.home],roof=w.home===2?92:w.home===1?68:120,height=w.home===2?98:w.home===1?122:70;
 const windows=(x,y,columns,rows)=>Array.from({length:rows},(_,row)=>Array.from({length:columns},(_,col)=>`<rect x="${x+col*22}" y="${y+row*22}" width="10" height="12" rx="1" fill="${row%2?'#63765b':'#bbd88d'}"/>`).join('')).join('');
 return `<div class="city-map city-map-visual"><div class="city-map-heading"><span class="eyebrow">ŞEHİR HARİTASI</span><span>${day(s)}. gün · ${w.reputation} itibar</span></div><svg class="city-illustration" viewBox="0 0 900 360" role="img" aria-label="Evin, mahallenin salonu, meydan ve maç alanı"><defs><pattern id="city-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#23332b" stroke-width=".8"/></pattern></defs><rect width="900" height="360" rx="20" fill="#15231d"/><rect width="900" height="360" rx="20" fill="url(#city-grid)"/><path d="M0 236H900M310 0V360M622 0V360" stroke="#34483a" stroke-width="34"/><path d="M0 236H900M310 0V360M622 0V360" stroke="#879378" stroke-width="2" stroke-dasharray="10 14"/><path d="M0 211H900M0 261H900" stroke="#688455" stroke-width="2" opacity=".5"/><g fill="#243b2b"><circle cx="45" cy="87" r="26"/><circle cx="260" cy="66" r="30"/><circle cx="552" cy="54" r="27"/><circle cx="673" cy="58" r="25"/><circle cx="854" cy="306" r="31"/><circle cx="63" cy="311" r="24"/></g><g><rect x="${w.home===2?91:103}" y="${roof}" width="${w.home===2?154:128}" height="${height}" rx="5" fill="${w.home===2?'#778777':'#536250'}"/><path d="M91 ${roof}L117 ${roof-21}H218L242 ${roof}Z" fill="${w.home===2?'#b9d4a1':'#879567'}"/>${windows(122,roof+17,w.home===2?5:4,w.home===1?4:2)}<rect x="158" y="161" width="24" height="29" fill="#213c2b"/><rect x="79" y="190" width="175" height="8" rx="4" fill="#657454"/></g><g><rect x="389" y="92" width="151" height="105" rx="5" fill="#526758"/><path d="M378 92L395 66H531L551 92Z" fill="#a4b381"/><rect x="409" y="108" width="111" height="31" rx="3" fill="#1c2f24"/><text x="465" y="130" text-anchor="middle" fill="#d8efb7" font-size="21" font-family="sans-serif" font-weight="700">GYM</text><rect x="443" y="153" width="43" height="44" fill="#233c2c"/><path d="M395 153H426M501 153H531" stroke="#97ac83" stroke-width="12"/></g><g><path d="M706 97L764 68L826 97L847 161L814 198H716L683 161Z" fill="#53694d"/><path d="M723 111L766 88L810 111L826 158L804 180H729L704 158Z" fill="#172b20" stroke="#b9dc83" stroke-width="3"/><path d="M723 111L804 180M810 111L729 180" stroke="#455b3d" stroke-width="2"/><circle cx="765" cy="140" r="20" fill="#b8d785"/><text x="765" y="146" text-anchor="middle" fill="#1d3121" font-size="16" font-family="sans-serif" font-weight="700">MMA</text></g><g><rect x="377" y="284" width="189" height="48" rx="22" fill="#516c40"/><circle cx="472" cy="307" r="21" fill="#95b06f"/><circle cx="472" cy="307" r="12" fill="#537b76"/><path d="M396 304H425M519 304H547" stroke="#bbbe81" stroke-width="7"/><circle cx="360" cy="296" r="8" fill="#b8d48a"/><circle cx="586" cy="324" r="8" fill="#b8d48a"/></g></svg><div class="city-landmarks"><button class="city-landmark" style="--x:19%;--y:48%" data-action="nav" data-value="home"><small>EVİN</small><strong>${esc(home.name)}</strong></button><button class="city-landmark" style="--x:52%;--y:48%" data-action="nav" data-value="gym"><small>SALON & EKİP</small><strong>Gym'e git</strong></button><button class="city-landmark" style="--x:85%;--y:48%" data-action="nav" data-value="fight"><small>MAÇ ALANI</small><strong>Kafese giden yol</strong></button><a class="city-landmark city-landmark-community" style="--x:52%;--y:87%" href="#city-events"><small>MAHALLE MEYDANI</small><strong>Günün fırsatları</strong></a></div><div class="city-map-links"><a href="#city-sponsors">Sponsorları gör</a><a href="#city-homes">Evini yükselt</a></div></div>`;
}

export function renderCity(s){
 const w=world(s),home=W.HOMES[w.home],sponsor=W.SPONSORS.find(x=>x.id===w.sponsor),taken=W.opportunityTaken(s),busy=!!s.fight&&!s.fight.done;
 const mood=w.reputation<4?'Adını duyurmaya başla.':w.reputation<12?'Mahalle seni tanıyor.':w.reputation<25?'Şehirde adın konuşuluyor.':'Artık salonların ötesinde tanınıyorsun.';
 const context=`<span class="eyebrow">ŞEHİRDEKİ HAYATIN</span><h2>${mood}</h2><div class="row"><div class="metric"><strong>${w.reputation}</strong>İtibar / 100</div><div class="metric"><strong>${day(s)}</strong>Oyun günü</div></div><div class="divider"></div><p><strong>${esc(home.name)}</strong><br>${esc(home.subtitle)}</p><p>${sponsor?'Sponsorun: <strong>'+esc(sponsor.name)+'</strong>':'İlk sponsorun 4 itibarla açılır. Maçlar ve mahalle etkinlikleri itibar kazandırır.'}</p><p class="world-notice" role="status">${esc(w.notice)}</p><p>Günde bir şehir fırsatı seçebilirsin. İşlemler yalnız gösterilen oyun süresini ilerletir; sen yokken zaman akmaz.</p>`;
 const content=`${cityMap(s)}<div id="city-events">${section('Bugün şehirde',day(s)+'. GÜN · BİR SEÇİM')}</div><p class="section-intro">${taken?'Bugünün etkinliği tamamlandı. Yarın pano yenilenir; sponsor ve ev seçeneklerini şimdi inceleyebilirsin.':'Bir fırsata katılmak bugünkü şehir seçimini kullanır. Ücret, kaynak tüketimi ve kazanımlar her seçeneğin altında.'}</p><div class="city-grid">${W.opportunities(s).map(e=>`<article class="card world-card"><span class="eyebrow">${esc(e.location)}</span><h3>${esc(e.name)}</h3><p>${esc(e.description)}</p>${e.choices.map(c=>{const campLocked=c.training&&(s.fatigue>=85||!!s.camp&&s.hours>=s.camp.dueAt);return `<div class="world-choice"><h4>${esc(c.label)}</h4><p>${esc(c.description)}</p>${costs(s,c)}${campLocked?'<p class="help-text">Antrenman yükün yüksekse toparlan; maç günü geldiyse önce maçını tamamla.</p>':''}${button(taken?'Bugün tamamlandı':c.label,'event:'+e.id+':'+c.id,taken||busy||campLocked)}</div>`}).join('')}</article>`).join('')}</div><div id="city-sponsors">${section('Köşenin dışındaki destek','1 AKTİF SPONSOR')}</div><p class="section-intro">Anlaşma ücretsizdir. Sponsor desteği galibiyet veya mağlubiyetten bağımsızdır; yalnız belirtilen liglerde ve oyun gününde en fazla bir kez ödenir. Yeni anlaşma öncekinin yerini alır.</p><div class="cards">${W.SPONSORS.map(x=>`<article class="card world-card ${w.sponsor===x.id?'equipped':''}"><span class="tag">${w.sponsor===x.id?'YANINDA':x.reputation+' İTİBAR GEREKLİ'}</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><span class="cost">Uygun maç başına +${money(x.payout)}<br>Anlaşma ücretsiz</span>${button(w.sponsor===x.id?'Sponsorun':w.reputation<x.reputation?'İtibar '+x.reputation+' gerekli':'Anlaşma yap','sponsor:'+x.id,busy||w.sponsor===x.id||w.reputation<x.reputation)}</article>`).join('')}</div>${w.sponsor?`<div class="inline-actions">${button('Sponsor anlaşmasını bitir','sponsor:none',busy,'ghost')}</div>`:''}<div id="city-homes">${section('Başını koyduğun yer','KALICI YÜKSELTME')}</div><div class="cards">${W.HOMES.map(x=>`<article class="card world-card ${w.home===x.id?'equipped':''}"><span class="eyebrow">${w.home===x.id?'EVİNDESİN':w.home>x.id?'GERİDE KALDI':x.reputation+' İTİBAR'}</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><span class="cost">${x.id?money(x.price)+' · Bir kez ödenir':'Kira veya düzenli kesinti yok'}</span>${x.id>w.home?button(w.reputation<x.reputation?'İtibar '+x.reputation+' gerekli':x.id!==w.home+1?'Önce kendi dairene geç':'Taşın · '+money(x.price),'home:'+x.id,busy||x.id!==w.home+1||w.reputation<x.reputation):'<span class="help-text">'+(w.home===x.id?'Mevcut evin':'Tamamlanan yaşam basamağı')+'</span>'}</article>`).join('')}</div><p class="help-text">Ev avantajları normal uyku ve dinlenmeye eklenir; enerji ve sağlık 100, antrenman yükü 0 sınırını aşmaz.</p>`;
 return {context,content,title:'Şehrin içinde <em>kendi yolunu aç.</em>'};
}
